    def _hstack(self, Xs, *, n_samples=None):
        """Stacks Xs.

        Xs is a list of either:
        - numpy arrays
        - sparse arrays
        - DataFrames
        - tuples of (array, feature_names)
        """
        if self._output_config["dense"]:
            return self._hstack_dense(Xs, n_samples=n_samples)
        else:
            return self._hstack_sparse(Xs, n_samples=n_samples)

    def _hstack_dense(self, Xs, *, n_samples=None):
        """Stacks dense Xs.

        Xs is a list of either:
        - numpy arrays
        - DataFrames
        - tuples of (array, feature_names)
        """
        if n_samples is None:
            n_samples = Xs[0].shape[0]

        if self._output_config["pandas"]:
            pd = check_pandas_support("transform")
            # When all the transformers return a dataframe, we use the
            # feature names to stack them.
            if all(hasattr(X, "columns") for X in Xs):
                names = []
                for X in Xs:
                    if isinstance(X, tuple):
                        names.extend(X[1])
                    else:
                        names.extend(X.columns)
                return pd.concat(Xs, axis=1), names

            # When only some of the transformers return a dataframe, we
            # need to convert the ones that don't to dataframes.
            for i, X in enumerate(Xs):
                if not hasattr(X, "columns"):
                    Xs[i] = pd.DataFrame(X, columns=self._get_feature_names_out(i))

            names = []
            for X in Xs:
                if isinstance(X, tuple):
                    names.extend(X[1])
                else:
                    names.extend(X.columns)
            return pd.concat(Xs, axis=1), names

