    def _hstack(self, Xs, *, transformers=None):
        """
        Stacks Xs horizontally.

        This allows custom ColumnTransformer to override the stacking behavior.
        """
        if transformers is None:
            transformers = self.transformers_
        n_jobs = self.n_jobs
        if len(Xs) == 0:
            # All transformers are None
            return np.zeros((self._n_features_in, 0), dtype=float)

        if self._output_config["dense"]:
            if any(sparse.issparse(X) for X in Xs):
                Xs = [
                    X.toarray() if sparse.issparse(X) else X for X in Xs
                ]
            return np.hstack(Xs)
        else:
            # When all the transformers are sparse, we use sparse.hstack.
            # If some are dense, we densify.
            if all(sparse.issparse(X) for X in Xs):
                return sparse.hstack(Xs).tocsr()
            else:
                Xs = [
                    X.toarray() if sparse.issparse(X) else X for X in Xs
                ]
                return np.hstack(Xs)
